const PLAN_ORDER = ['l1', 'l10', 'l11', 'l12', 'l13', 'l14', 'l15', 'l16', 'l2', 'l3', 'l4', 'l5', 'l6', 'l17', 'l7', 'l8', 'l9', 'l18', 'l19', 'l20', 'l21', 'l22', 'l23', 'l24', 'l25', 'l26', 'l27'];
