function orderLessons() { const r = new Map(PLAN_ORDER.map((id, k) => [id, k])); LESSONS.sort((a, b) => (r.has(a.id) ? r.get(a.id) : 999) - (r.has(b.id) ? r.get(b.id) : 999)); }
orderLessons();

